    expect(canUpgradeStatus('Landed', 'Boarding')).toBe(false);
  });

  it('allows same-priority transitions', () => {
    expect(canUpgradeStatus('Landed', 'Cancelled')).toBe(true);
    expect(canUpgradeStatus('Cancelled', 'Landed')).toBe(true);
