export type NewNotificationWatermark = typeof schema.notificationWatermark.$inferInsert;
export { tryAcquireServiceLock } from './singleton';
export {
  clearAllTimers,
  countFlightsForDate,
  getActiveFlightsToday,
  getEstimatedTimesBatch,
  msSinceLastScrape,
  logSchedulerEvent,
  computeNextInterval,
  shouldSleep,
